external class JQuery {
    companion object {
        fun get(settings: JQueryAjaxSettings): JQueryXHR
    }
}

fun sendQuery() {
    JQuery.get(JQueryAjaxSettings().apply {
        complete = { (xhr, data) ->
            window.alert("Request complete")
        }
    })
}","title":"Use JavaScript code from Kotlin","source":"https://kotlinlang.org/docs/js-interop.html","sections":["Use JavaScript code from Kotlin > external modifier > external interfaces"],"line_start":126,"line_end":166,"score":0.5921867489814758,"release_version":null,"availability":"unknown"}]}

